#include "stdlib/lapack/base/dpstf2.h"
#include "validate.h"

/**
* Computes a complete-pivoting Cholesky factorization of a symmetric matrix.
*
* @param layout  storage layout
* @param uplo    selected triangle
* @param N       matrix order
* @param A       input/output matrix
* @param LDA     leading dimension
* @param PIV     complete positive one-based permutation output
* @param RANK    rank output
* @param TOL     finite pivot tolerance; negative selects the default
* @param WORK    2N-element scratch
* @return        INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpstf2)( const LAPACK_LAYOUT layout, const LAPACK_UPLO uplo, const LAPACK_INT N, double *A, const LAPACK_INT LDA, LAPACK_INT *PIV, LAPACK_INT *RANK, const double TOL, double *WORK ) {
	LAPACK_INT stride1;
	LAPACK_INT stride2;
	LAPACK_INT info;

	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) return dpstf2_error( "c_dpstf2", -1 );
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return dpstf2_error( "c_dpstf2", -2 );
	if ( N < 0 || (intmax_t)N > dpstf2_lapack_max()/2 ) return dpstf2_error( "c_dpstf2", -3 );
	if ( !isfinite( TOL ) ) return dpstf2_error( "c_dpstf2", -8 );
	if ( LDA < 1 || LDA < N ) return dpstf2_error( "c_dpstf2", -5 );
	stride1 = layout == LAPACK_COL_MAJOR ? 1 : LDA;
	stride2 = layout == LAPACK_COL_MAJOR ? LDA : 1;
	info = dpstf2_validate( 1, uplo, N, A, stride1, stride2, 0, PIV, 1, 0, RANK, 0, TOL, WORK, 1, 0 );
	if ( info != 0 ) return dpstf2_error( "c_dpstf2", info );
	return API_SUFFIX(c_dpstf2_ndarray)( uplo, N, A, stride1, stride2, 0, PIV, 1, 0, RANK, 0, TOL, WORK, 1, 0 );
}
